assignments.referenceSolution:
`__init_subclass__` computes the key, validates the contract, rejects duplicates and only then records the class. Validation happens before registration, so a rejected class never appears in the registry. No metaclass is involved, so there is no metaclass-conflict risk when providers also inherit from ABCs or ORM mixins.

**`providers.py`**

```python
from __future__ import annotations

from typing import Any, ClassVar


class UnknownProvider(KeyError):
    """Raised when no provider is registered under the requested name."""


class Provider:
    """Base class: subclasses register themselves at class-creation time."""

    registry: ClassVar[dict[str, type["Provider"]]] = {}
    name: ClassVar[str]

    def __init_subclass__(cls, *, name: str | None = None, **kwargs: Any) -> None:
        super().__init_subclass__(**kwargs)
        key = name if name is not None else cls.__name__.lower()
        if cls.complete is Provider.complete:
            raise TypeError(f"{cls.__name__} must override complete()")
        if key in Provider.registry:
            raise TypeError(f"duplicate provider name {key!r}")
        cls.name = key
        Provider.registry[key] = cls

    def complete(self, prompt: str) -> str:
        raise NotImplementedError

    @classmethod
    def create(cls, name: str, **config: Any) -> "Provider":
        try:
            provider_cls = Provider.registry[name]
        except KeyError:
            known = ", ".join(sorted(Provider.registry)) or "none"
            raise UnknownProvider(f"unknown provider {name!r}; known: {known}") from None
        return provider_cls(**config)
```

**`test_providers.py`**

```python
import pytest

from providers import Provider, UnknownProvider


@pytest.fixture(autouse=True)
def clean_registry():
    saved = dict(Provider.registry)
    yield
    Provider.registry.clear()
    Provider.registry.update(saved)


def test_subclass_registers_itself_with_default_and_explicit_names() -> None:
    class OpenAI(Provider):
        def complete(self, prompt: str) -> str:
            return "openai:" + prompt

    class Local(Provider, name="llama"):
        def complete(self, prompt: str) -> str:
            return "llama:" + prompt

    assert Provider.registry["openai"] is OpenAI
    assert Provider.registry["llama"] is Local
    assert OpenAI.name == "openai" and Local.name == "llama"


def test_duplicate_names_fail_at_class_creation() -> None:
    class A(Provider, name="dup"):
        def complete(self, prompt: str) -> str:
            return prompt

    with pytest.raises(TypeError, match="duplicate"):
        class B(Provider, name="dup"):
            def complete(self, prompt: str) -> str:
                return prompt


def test_missing_complete_fails_at_class_creation() -> None:
    with pytest.raises(TypeError, match="complete"):
        class Broken(Provider):
            pass

    assert "broken" not in Provider.registry


def test_create_passes_config_and_unknown_raises() -> None:
    class Echo(Provider):
        def __init__(self, prefix: str = "") -> None:
            self.prefix = prefix

        def complete(self, prompt: str) -> str:
            return self.prefix + prompt

    p = Provider.create("echo", prefix=">> ")
    assert p.complete("hi") == ">> hi"
    with pytest.raises(UnknownProvider, match="known: .*echo"):
        Provider.create("nope")


def test_subclass_of_subclass_inherits_complete_and_registers() -> None:
    class Base(Provider, name="base"):
        def complete(self, prompt: str) -> str:
            return "base"

    class Child(Base, name="child"):
        pass

    assert Provider.create("child").complete("x") == "base"
```

Run the tests with `pytest -q`.

The metaclass does three things only a metaclass can do cleanly: it supplies the class-body namespace (`__prepare__`), it post-processes the finished class in `__new__` while consuming its own keyword (`table`), and it installs `__signature__` so tooling sees real parameters. Everything else (field naming) is delegated to `__set_name__`. Compare with `__init_subclass__`: field collection alone would not need a metaclass, but the duplicate-name check does.

**`declarative.py`**

```python
from __future__ import annotations

import inspect
from typing import Any

_MISSING: Any = object()


class Field:
    """Non-data descriptor declaring a column; the value lives in the instance __dict__."""

    def __init__(self, column_type: str, *, default: Any = _MISSING) -> None:
        self.column_type = column_type
        self.default = default
        self.name = ""

    def __set_name__(self, owner: type, name: str) -> None:
        self.name = name

    def __get__(self, obj: object | None, objtype: type | None = None) -> Any:
        if obj is None:
            return self
        if self.default is _MISSING:
            raise AttributeError(self.name)
        return self.default


class _Namespace(dict[str, Any]):
    """Class-body namespace that rejects redefinition of non-dunder names."""

    def __setitem__(self, key: str, value: Any) -> None:
        dunder = key.startswith("__") and key.endswith("__")
        if key in self and not dunder:
            raise TypeError(f"duplicate definition of {key!r}")
        super().__setitem__(key, value)


class ModelMeta(type):
    __fields__: dict[str, Field]
    __table__: str

    @classmethod
    def __prepare__(mcs, name: str, bases: tuple[type, ...], **kwargs: Any) -> _Namespace:
        return _Namespace()

    def __new__(
        mcs,
        name: str,
        bases: tuple[type, ...],
        ns: dict[str, Any],
        *,
        table: str | None = None,
        **kwargs: Any,
    ) -> "ModelMeta":
        cls = super().__new__(mcs, name, bases, dict(ns), **kwargs)
        fields: dict[str, Field] = {}
        for base in reversed(cls.__mro__[1:]):
            fields.update(getattr(base, "__fields__", {}))
        fields.update({k: v for k, v in ns.items() if isinstance(v, Field)})
        cls.__fields__ = fields
        cls.__table__ = table or name.lower() + "s"
        cls.__signature__ = inspect.Signature(  # type: ignore[attr-defined]
            [
                inspect.Parameter(
                    n,
                    inspect.Parameter.KEYWORD_ONLY,
                    default=inspect.Parameter.empty if f.default is _MISSING else f.default,
                )
                for n, f in fields.items()
            ]
        )
        return cls


class Model(metaclass=ModelMeta):
    def __init__(self, **kwargs: Any) -> None:
        bound = type(self).__signature__.bind(**kwargs)  # type: ignore[attr-defined]
        bound.apply_defaults()
        self.__dict__.update(bound.arguments)

    @classmethod
    def create_sql(cls) -> str:
        cols = ", ".join(f"{n} {f.column_type}" for n, f in cls.__fields__.items())
        return f"CREATE TABLE {cls.__table__} ({cols})"
```

**`test_declarative.py`**

```python
import inspect

import pytest

from declarative import Field, Model


class Ticket(Model):
    id = Field("INTEGER PRIMARY KEY")
    title = Field("TEXT")
    status = Field("TEXT", default="open")


class Bug(Ticket, table="defects"):
    severity = Field("INTEGER", default=3)


def test_fields_are_collected_in_declaration_order_with_inheritance() -> None:
    assert list(Ticket.__fields__) == ["id", "title", "status"]
    assert list(Bug.__fields__) == ["id", "title", "status", "severity"]
    assert "severity" not in Ticket.__fields__


def test_table_names_and_keyword_forwarding() -> None:
    assert Ticket.__table__ == "tickets"
    assert Bug.__table__ == "defects"


def test_create_sql() -> None:
    assert Ticket.create_sql() == (
        "CREATE TABLE tickets (id INTEGER PRIMARY KEY, title TEXT, status TEXT)"
    )
    assert Bug.create_sql().startswith("CREATE TABLE defects (")


def test_generated_signature_and_defaults() -> None:
    sig = inspect.signature(Bug)
    assert list(sig.parameters) == ["id", "title", "status", "severity"]
    t = Bug(id=1, title="boom")
    assert (t.id, t.title, t.status, t.severity) == (1, "boom", "open", 3)


def test_missing_and_unknown_arguments_raise_type_error() -> None:
    with pytest.raises(TypeError):
        Ticket(id=1)  # title is required
    with pytest.raises(TypeError):
        Ticket(id=1, title="x", colour="red")


def test_duplicate_definitions_fail_at_class_creation() -> None:
    with pytest.raises(TypeError, match="duplicate definition of 'title'"):
        class Bad(Model):
            title = Field("TEXT")
            title = Field("VARCHAR(10)")


def test_class_access_returns_field() -> None:
    assert isinstance(Ticket.title, Field)
    assert Ticket.title.name == "title"
```

Run the tests with `pytest -q`.
